export function getVerifiedSecuritiesLedgerManifests() {
  return structuredClone(LEDGERS);
}

export function getVerifiedSecuritiesFacts({ sourceId, sourceVersion } = {}) {
  return structuredClone(
    FACTS.filter((fact) => fact.sourceId === sourceId && fact.sourceVersion === sourceVersion),
  );
}

function sameValue(value, canonical) {
  if (value === canonical) return true;
  if (
    !value ||
    !canonical ||
    typeof value !== "object" ||
    typeof canonical !== "object" ||
    Array.isArray(value) !== Array.isArray(canonical)
  )
    return false;
  const keys = Object.keys(canonical);
  return (
    Object.keys(value).length === keys.length &&
    keys.every((key) => Object.hasOwn(value, key) && sameValue(value[key], canonical[key]))
  );
}

export function matchVerifiedSecuritiesFact(value) {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const found = FACTS.find((fact) => fact.factId === value.factId && sameValue(value, fact));
  return found ? structuredClone(found) : null;
}
